package com.beeboee.magnot.client;import com.beeboee.magnot.region.FerrousRegion;import net.minecraft.util.math.vector.Vector3d;import java.util.*;public final class ClientRegionStore{private static List<FerrousRegion>rs=Collections.emptyList();private ClientRegionStore(){}public static void set(List<FerrousRegion>v){rs=Collections.unmodifiableList(new ArrayList<FerrousRegion>(v));}public static void clear(){rs=Collections.emptyList();}public static List<FerrousRegion>all(){return rs;}public static Optional<FerrousRegion>selected(Vector3d a,Vector3d b){FerrousRegion best=null;double d=Double.MAX_VALUE;for(FerrousRegion r:rs){Optional<Double>h=r.hitDistanceSqr(a,b);if(h.isPresent()&&h.get()<d){d=h.get();best=r;}}return Optional.ofNullable(best);}}
